from collections import defaultdict, deque

# Global storage for recent actions per donor (limited window)
agent_memory = defaultdict(lambda: deque(maxlen=10))  # last 10 actions per donor

def evaluate(current_reputation, observation, my_history, round_num):
    # Use the 'recent_window' field if present; otherwise fall back to single observation
    window = observation.get('recent_window', [])
    if window:
        # Process all observed transactions in the window
        for entry in window:
            donor = entry.get('donor')
            action = entry['action']
            if donor:
                agent_memory[donor].append(1.0 if action == 'cooperate' else -1.0)
    else:
        # Legacy mode: single observation via 'donor' field
        donor = observation.get('donor')
        action = observation['action']
        if donor:
            agent_memory[donor].append(1.0 if action == 'cooperate' else -1.0)

    # For the specific donor of interest (if any), compute average over recent window
    donor = observation.get('donor', None)
    if donor and donor in agent_memory:
        records = list(agent_memory[donor])
        if records:
            # Simple average without decay (uniform weight)
            avg = sum(records) / len(records)
            return max(-1.0, min(1.0, avg))
    # Fallback to current reputation if no data
    return current_reputation


def decide(recipient_reputation, round_num, my_history):
    # Compute own cooperation rate from my_history (third element is my_action)
    if len(my_history) == 0:
        own_coop_rate = 1.0  # start cooperative
    else:
        own_coop_count = sum(1 for entry in my_history if entry[2] == 'cooperate')
        own_coop_rate = own_coop_count / len(my_history)

    # Be more generous early, stricter later
    if round_num <= 5:
        # Early: cooperate unless recipient has a very bad reputation
        return recipient_reputation > -0.5
    elif round_num <= 10:
        # Middle: cooperative if reputation is positive or own cooperation is high
        return recipient_reputation >= 0.0 or (own_coop_rate > 0.7 and recipient_reputation > -0.3)
    else:
        # Late: conditional on reputation and own history
        return recipient_reputation > 0.3 and own_coop_rate > 0.4

